// The PWA icons (#336): the app's own icon, flattened full-bleed (iOS rounds the corners) — bytes in icons-data.ts, generated by
// scripts/gen-acces-mobile-icons.py. Served by server.ts behind the SAME identity check as every other asset.

import { ICON_180_PNG_B64, ICON_192_PNG_B64, ICON_512_PNG_B64 } from './icons-data.ts';

export interface PwaIcon {
  path: string;
  size: number;
  png: Buffer;
}

/** `/apple-touch-icon.png` is what iOS reads for the home-screen icon (it ignores the manifest's); the other two are the manifest's. */
export const APPLE_TOUCH_ICON_PATH = '/apple-touch-icon.png';

export const PWA_ICONS: readonly PwaIcon[] = [
  { path: APPLE_TOUCH_ICON_PATH, size: 180, png: Buffer.from(ICON_180_PNG_B64, 'base64') },
  { path: '/icon-192.png', size: 192, png: Buffer.from(ICON_192_PNG_B64, 'base64') },
  { path: '/icon-512.png', size: 512, png: Buffer.from(ICON_512_PNG_B64, 'base64') },
];

export const MANIFEST_ICONS = PWA_ICONS.filter((i) => i.path !== APPLE_TOUCH_ICON_PATH).map((i) => ({
  src: i.path,
  sizes: `${i.size}x${i.size}`,
  type: 'image/png',
  purpose: 'any',
}));
